/**
 * Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  TOAST_QUIET,
  actOnToastNotice,
  agentMember,
  announceToasts,
  cell,
  derived,
  dismissToastNotice,
  elementRef,
  followToastFocus,
  getToasts,
  holdToastTimers,
  mountEffect,
  subscribeToasts,
  toast,
  toastDetails,
  toastNotices,
  useMember,
  watchEffect,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import { ToastCard, type ToastCardProps } from './ToastCard'
import type { ToasterMessages } from './Toast'

/** Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds: the inputs it takes, by the React member's prop names. */
export interface ToastViewportProps {
  /**
   * The close button’s name, the announcement’s prefix and the region’s name, from the catalog.
   */
  messages?: ToasterMessages
}

/** Toast.Viewport: the one viewport the application mounts, which draws every toast the store holds. */
@Component({
  selector: 'pm-toast-viewport',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, ToastCard],
  // prettier-ignore
  template: `<!-- region -->
<div
role="region"
[attr.aria-label]="e1()"
tabindex="-1"
[pmRef]="region"
><!-- list -->
<ol
[attr.class]="e2()"
tabindex="-1"
data-toast-part="list"
[pmRef]="list"
>@for (record of e3(); track e4(record)) {<li
pmToastCard
[record]="e5(record)"
[dismissLabel]="e6()"
[paused]="e7()"
></li>}</ol>
<!-- polite -->
<div
[attr.class]="e8()"
role="status"
aria-live="polite"
aria-atomic="true"
>@for (saying of e9(); track e10(saying)) {<!-- saying -->
<span>{{ e11(saying) }}</span>}</div>
<!-- assertive -->
<div
[attr.class]="e8()"
role="alert"
aria-live="assertive"
aria-atomic="true"
>@for (saying of e12(); track e13(saying)) {<!-- urgent -->
<span>{{ e14(saying) }}</span>}</div></div>`,
})
export class ToastViewport {
  /**
   * The close button’s name, the announcement’s prefix and the region’s name, from the catalog.
   */
  readonly messages = input<ToastViewportProps['messages']>(undefined)
  protected readonly $ = useMember({ events: [], props: { messages: () => this.messages() } })
  protected readonly $p = this.$.props
  protected readonly version = cell(() => 0)
  protected readonly paused = cell(() => false)
  protected readonly said = cell(() => TOAST_QUIET)
  protected readonly list = elementRef<HTMLElement>()
  protected readonly region = elementRef<HTMLElement>()
  protected readonly say = derived(
    () =>
      this.$p.messages ?? {
        dismiss: 'Dismiss',
        notification: 'Notification',
        viewport: 'Notifications (F8)',
      },
  )
  protected readonly records = derived(() => (this.version.value < 0 ? [] : getToasts()))
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined
  private release4: (() => void) | undefined
  private release6: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
    inject(DestroyRef).onDestroy(() => this.release4?.())
    mountEffect(() => this.effect4())
    watchEffect(
      () => this.version.value,
      () => this.effect5(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release6?.())
    mountEffect(() => this.effect6())
  }

  protected e1() {
    return this.say.value.viewport
  }

  protected e2() {
    return styles.viewport
  }

  e3() {
    return this.records.value
  }

  protected e4(record: Each<ReturnType<ToastViewport['e3']>>) {
    return record.id
  }

  protected e5(record: Each<ReturnType<ToastViewport['e3']>>): ToastCardProps['record'] {
    return record
  }

  protected e6(): ToastCardProps['dismissLabel'] {
    return this.say.value.dismiss
  }

  protected e7(): ToastCardProps['paused'] {
    return this.paused.value
  }

  protected e8() {
    return a11y.visuallyHidden
  }

  e9() {
    return [this.said.value.polite]
  }

  protected e10(saying: Each<ReturnType<ToastViewport['e9']>>) {
    return saying.key
  }

  protected e11(saying: Each<ReturnType<ToastViewport['e9']>>) {
    return saying.words
  }

  e12() {
    return [this.said.value.assertive]
  }

  protected e13(saying: Each<ReturnType<ToastViewport['e12']>>) {
    return saying.key
  }

  protected e14(saying: Each<ReturnType<ToastViewport['e12']>>) {
    return saying.words
  }

  private effect1(): void {
    this.release1?.()
    const ran =
      ((this.version.value += 1),
      subscribeToasts(() => {
        this.version.value += 1
      }))
    this.release1 = () => {
      ran()
    }
  }

  private effect2(): void {
    this.release2?.()
    const listener = ($event: KeyboardEvent) => {
      void ($event.key === 'F8' && ($event.preventDefault(), this.list.value?.focus()))
    }
    document.addEventListener('keydown', listener)
    this.release2 = () => document.removeEventListener('keydown', listener)
  }

  private effect3(): void {
    this.release3?.()
    const ran = holdToastTimers(this.region.value, (held) => {
      this.paused.value = held
    })
    this.release3 = () => {
      ran()
    }
  }

  private effect4(): void {
    this.release4?.()
    const ran = followToastFocus(this.list.value)
    this.release4 = () => {
      ran()
    }
  }

  private effect5(): void {
    this.said.value = announceToasts(
      this.said.value,
      this.records.value,
      this.list.value,
      this.say.value.notification,
    )
  }

  private effect6(): void {
    this.release6?.()
    const ran = agentMember({
      member: 'Toast',
      element: () => this.region.value,
      state: () => ({ notices: toastNotices(getToasts()), details: toastDetails(getToasts()) }),
      actions: {
        dismiss: { argument: 'id', run: (value) => dismissToastNotice(toast, getToasts(), value) },
        act: { argument: 'id', run: (value) => actOnToastNotice(toast, getToasts(), value) },
      },
      withholds: () => [
        ...(this.list.value?.querySelectorAll('[data-member="toast"] > div ~ div') ?? []),
      ],
    })
    this.release6 = () => {
      ran()
    }
  }
}
